# ==============================================================================# 050_MASTER_CONTROL.py# ==============================================================================import sqlite3from pathlib import Pathfrom datetime import datetimeROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"conn = sqlite3.connect(DB, timeout=30)conn.row_factory = sqlite3.Rowcur = conn.cursor()

cur.execute("PRAGMA journal_mode=WAL")
cur.execute("PRAGMA synchronous=NORMAL")
cur.execute("PRAGMA busy_timeout=30000")# ==============================================================================# MASTER CONTROL TABLE# ==============================================================================cur.execute("""CREATE TABLE IF NOT EXISTS master_control(    id INTEGER PRIMARY KEY AUTOINCREMENT,    created_at TEXT,    system_status TEXT,    health REAL,    total_services INTEGER,    services_online INTEGER,    pending_commands INTEGER,    pending_tasks INTEGER,    active_alerts INTEGER,    orchestrator_actions INTEGER,    decision TEXT)""")conn.commit()# ==============================================================================# HEALTH# ==============================================================================cur.execute("""SELECT healthFROM runtime_monitorORDER BY id DESCLIMIT 1""")row = cur.fetchone()health = row["health"] if row else 0# ==============================================================================# SERVICES# ==============================================================================cur.execute("SELECT COUNT(*) FROM services")total_services = cur.fetchone()[0]cur.execute("""SELECT COUNT(*)FROM runtimeWHERE status='READY'""")services_online = cur.fetchone()[0]# ==============================================================================# COMMANDS# ==============================================================================cur.execute("""SELECT COUNT(*)FROM command_busWHERE status='PENDING'""")pending_commands = cur.fetchone()[0]# ==============================================================================# TASKS# ==============================================================================cur.execute("""SELECT COUNT(*)FROM task_queueWHERE status='PENDING'""")pending_tasks = cur.fetchone()[0]# ==============================================================================# ALERTS# ==============================================================================cur.execute("""SELECT COUNT(*)FROM alertsWHERE status='OPEN'""")active_alerts = cur.fetchone()[0]# ==============================================================================# ORCHESTRATOR# ==============================================================================cur.execute("""SELECT COUNT(*)FROM orchestratorWHERE status='READY'""")orchestrator_actions = cur.fetchone()[0]# ==============================================================================# DECISION# ==============================================================================decision = "SYSTEM_RUNNING"if health < 95:    decision = "RUN_HEALTH_CHECK"if pending_commands > 0:    decision = "PROCESS_COMMANDS"if pending_tasks > 0:    decision = "PROCESS_TASKS"cur.execute("""SELECTpriorityFROM orchestratorWHERE status='READY'ORDER BYCASE priorityWHEN 'CRITICAL' THEN 1WHEN 'HIGH' THEN 2WHEN 'NORMAL' THEN 3WHEN 'LOW' THEN 4ENDLIMIT 1""")critical = cur.fetchone()if critical and critical["priority"] == "CRITICAL":    decision = "EXECUTE_CRITICAL_ACTION"# ==============================================================================# STATUS# ==============================================================================status = "ONLINE"if health < 80:    status = "DEGRADED"if health < 50:    status = "CRITICAL"# ==============================================================================# SAVE# ==============================================================================cur.execute("""INSERT INTO master_control(    created_at,    system_status,    health,    total_services,    services_online,    pending_commands,    pending_tasks,    active_alerts,    orchestrator_actions,    decision)VALUES(?,?,?,?,?,?,?,?,?,?)""",(    datetime.now().isoformat(),    status,    health,    total_services,    services_online,    pending_commands,    pending_tasks,    active_alerts,    orchestrator_actions,    decision))conn.commit()# ==============================================================================# DASHBOARD# ==============================================================================cur.execute("""SELECT *FROM master_controlORDER BY id DESCLIMIT 1""")m = cur.fetchone()print("="*80)print("MASTER CONTROL")print("="*80)print(f"STATUS..................: {m['system_status']}")print(f"HEALTH..................: {m['health']:.2f}%")print(f"SERVICES.................: {m['services_online']}/{m['total_services']}")print(f"COMMANDS PENDENTES.......: {m['pending_commands']}")print(f"TAREFAS PENDENTES........: {m['pending_tasks']}")print(f"ALERTAS ATIVOS...........: {m['active_alerts']}")print(f"AÃ‡Ã•ES DO ORQUESTRADOR....: {m['orchestrator_actions']}")print("-"*80)print(f"DECISÃƒO GLOBAL...........: {m['decision']}")print("="*80)conn.close()

